with filtered as (select *, coalesce(location, 'unassigned') as location_filled, ceil(budget) as budget_whole from departments where dept_name is not null), remaining_keys as (select location, dept_name from filtered except distinct select location, dept_name from departments where location not in ('London', 'Chiang Mai', 'New York')), kept_rows as (select s.* from filtered s join remaining_keys k on s.location = k.location and s.dept_name = k.dept_name), kept as (select s.* from kept_rows s where not exists (select 1 from employees c where c.dept_id = s.id and c.is_remote)), filtered_departments as (select dept_name, location, budget, location_filled, budget_whole, round(budget_whole, 0) as budget_whole_rounded, coalesce(location, 'UNKNOWN') as resolved_location from kept where location is not null and dept_name is not distinct from 'Finance'), with_windows as (select dept_name, location, cume_dist() over (order by budget desc nulls first) as budget_cume_dist, rank() over (partition by dept_name order by budget desc nulls first) as budget_rank from filtered_departments where budget_whole = 72) select case when budget_cume_dist >= 0.71 then 'LARGE' else 'SMALL' end as budget_cume_dist_tier, case when budget_rank >= 9 then 'HIGH' else 'LOW' end as budget_rank_tier, dept_name, sum(budget_rank) as total_budget_rank, approx_percentile(budget_cume_dist, array(0.25, 0.5, 0.75)) as budget_cume_dist_quartiles, count_if(dept_name = 'Sales') as sales_events from with_windows group by rollup (case when budget_cume_dist >= 0.71 then 'LARGE' else 'SMALL' end, case when budget_rank >= 9 then 'HIGH' else 'LOW' end, dept_name) order by budget_cume_dist_tier desc nulls first
